patch:
diff --git a/repro/windows-cross-drive.js b/repro/windows-cross-drive.js
new file mode 100644
index 0000000..031eaf1
--- /dev/null
+++ b/repro/windows-cross-drive.js
@@ -0,0 +1,77 @@
+"use strict";
+
+/*
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ * Runs on any OS: after loading ESLint, the shared `path` module is switched
+ * to Windows semantics (path.win32), which is what Node uses on win32.
+ * Usage: node repro/windows-cross-drive.js
+ */
+
+const path = require("node:path");
+const { Linter, ESLint } = require("../lib/api");
+const { FlatConfigArray } = require("../lib/config/flat-config-array");
+
+// Load lazily-required modules before path semantics change.
+require("../lib/rules").get("no-undef");
+
+if (process.platform !== "win32") {
+    Object.assign(path, path.win32);
+}
+
+const cwd = "C:\\Project";
+const config = { rules: { "no-undef": "error" } };
+const files = {
+    "inside cwd (should lint)": "C:\\Project\\foo.js",
+    "same drive, outside cwd (should be ignored)": "C:\\Other\\foo.js",
+    "different drive (should be ignored)": "F:\\foo.js"
+};
+
+let failed = false;
+
+console.log(`path.relative(${JSON.stringify(cwd)}, "C:\\\\Other\\\\foo.js") = ${JSON.stringify(path.relative(cwd, "C:\\Other\\foo.js"))}`);
+console.log(`path.relative(${JSON.stringify(cwd)}, "F:\\\\foo.js")         = ${JSON.stringify(path.relative(cwd, "F:\\foo.js"))}\n`);
+
+function check(label, filePath, actual) {
+    const expected = label.includes("should lint") ? false : true;
+    const ok = actual === expected;
+
+    if (!ok) {
+        failed = true;
+    }
+    console.log(`  ${ok ? "ok  " : "BUG "} ${filePath.padEnd(20)} ignored=${actual} (expected ${expected})  [${label}]`);
+}
+
+(async () => {
+    console.log("1) FlatConfigArray (basePath = cwd) - getConfigStatus():");
+    const configArray = new FlatConfigArray([config], { basePath: cwd });
+
+    await configArray.normalize();
+    for (const [label, filePath] of Object.entries(files)) {
+        const status = configArray.getConfigStatus(filePath);
+
+        check(`${label}; status=${status}`, filePath, status !== "matched");
+    }
+
+    console.log("\n2) Linter#verify('foo()'):");
+    const linter = new Linter({ configType: "flat", cwd });
+
+    for (const [label, filePath] of Object.entries(files)) {
+        const messages = linter.verify("foo()", config, filePath);
+        const linted = messages.some(m => m.ruleId === "no-undef");
+
+        check(`${label}; messages=${JSON.stringify(messages.map(m => m.ruleId ?? m.message))}`, filePath, !linted);
+    }
+
+    console.log("\n3) ESLint#lintText (like `eslint --no-config-lookup`):");
+    const eslint = new ESLint({ cwd, overrideConfigFile: true, overrideConfig: config });
+
+    for (const [label, filePath] of Object.entries(files)) {
+        const [result] = await eslint.lintText("foo();", { filePath, warnIgnored: true });
+        const ignored = result.messages.length === 1 && /ignored/u.test(result.messages[0].message);
+
+        check(`${label}; messages=${JSON.stringify(result.messages.map(m => m.ruleId ?? m.message))}`, filePath, ignored);
+    }
+
+    console.log(failed ? "\nBUG REPRODUCED: file on a different drive is not ignored." : "\nNo bug: all files handled as expected.");
+    process.exitCode = failed ? 1 : 0;
+})();
